exercises.solution:
class Recorder:
    def __init__(self, events):
        self.events = events

    def __enter__(self):
        self.events.append("enter")
        return self

    def __exit__(self, exc_type, exc, tb):
        self.events.append(f"exit:{exc_type.__name__}" if exc_type else "exit")
        return False

